#[cfg(test)]
mod tests {
    use super::*;

    fn build(v: &[i32]) -> Bst<i32> {
        let mut t = Bst::new();
        for &x in v {
            t.insert(x);
        }
        t
    }

    #[test]
    fn example() {
        let t = build(&[5, 3, 8, 1, 4]);
        assert_eq!(t.in_order(), vec![&1, &3, &4, &5, &8]);
        assert_eq!(t.height(), 3);
        assert_eq!(t.len(), 5);
        assert_eq!(t.range_count(&2, &5), 3);
    }

    #[test]
    fn empty_tree() {
        let t: Bst<i32> = Bst::new();
        assert_eq!(t.len(), 0);
        assert_eq!(t.height(), 0);
        assert_eq!(t.min(), None);
        assert_eq!(t.max(), None);
        assert!(t.in_order().is_empty());
        assert!(!t.contains(&1));
        assert_eq!(t.range_count(&0, &10), 0);
    }

    #[test]
    fn duplicates_and_contains() {
        let mut t = build(&[2, 1, 3]);
        assert!(!t.insert(2));
        assert!(t.insert(0));
        assert_eq!(t.len(), 4);
        assert!(t.contains(&0) && t.contains(&3));
        assert!(!t.contains(&7));
        assert_eq!(t.min(), Some(&0));
        assert_eq!(t.max(), Some(&3));
    }

    #[test]
    fn strings() {
        let mut t = Bst::new();
        for w in ["pear", "apple", "fig", "zucchini"] {
            t.insert(w.to_string());
        }
        let v: Vec<&str> = t.in_order().into_iter().map(|s| s.as_str()).collect();
        assert_eq!(v, vec!["apple", "fig", "pear", "zucchini"]);
        assert_eq!(t.range_count(&"b".to_string(), &"q".to_string()), 2);
    }

    #[test]
    fn degenerate_sorted_input() {
        let mut t = Bst::new();
        for i in 0..2000 {
            assert!(t.insert(i));
        }
        assert_eq!(t.height(), 2000);
        assert_eq!(t.range_count(&100, &199), 100);
        assert_eq!(t.max(), Some(&1999));
    }
}
